    void duplicateTimestampUploadRejected() {
        long batchId = newBatch();
        List<KilnDtos.PointInput> points = new ArrayList<>(KilnTestSupport.fullTrajectory());
        service.uploadPoints(batchId, KilnTestSupport.upload("up-1", points));

