                        Integer records = jdbc.queryForObject(
                                "SELECT COUNT(*) FROM kiln_release_record WHERE batch_id = ?",
                                Integer.class, batchId);
                        assertTrue(records <= 1);
                    }
                }
            }
        } finally {
            pool.shutdownNow();
        }
    }
}
